import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

fused_mish2_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float mish(const float x) {
    // mish = x * tanh(softplus(x))
    return x * tanhf(log1pf(expf(x)));
}

__global__ void fused_mish2_kernel(const float* __restrict__ input,
                                   float* __restrict__ output,
                                   const int size) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        // first mish
        val = mish(val);
        // second mish
        val = mish(val);
        output[idx] = val;
    }
}

torch::Tensor fused_mish2_forward(torch::Tensor x) {
    auto output = torch::zeros_like(x);
    const int size = x.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;
    fused_mish2_kernel<<<blocks, threads>>>(x.data_ptr<float>(),
                                           output.data_ptr<float>(),
                                           size);
    return output;
}
"""

fused_mish2_cpp_source = r"""
torch::Tensor fused_mish2_forward(torch::Tensor x);
"""

fused_mish2 = load_inline(
    name="fused_mish2",
    cpp_sources=fused_mish2_cpp_source,
    cuda_sources=fused_mish2_source,
    functions=["fused_mish2_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

    def forward(self, x):
        x = self.conv(x)
        x = fused_mish2.fused_mish2_forward(x)
        return x

def get_inputs():
    batch_size = 128
    in_channels = 3
    height, width = 32, 32
    return [torch.randn(batch_size, in_channels, height, width).cuda()]

